python - "$(inputs.metadata.path)" "$(inputs.samples.path)" "$(inputs.expression.path)" correlations.tsv <<'PY'
import csv
import math
import sys
from scipy.stats import pearsonr

metadata_path = sys.argv[1]
samples_path = sys.argv[2]
expression_path = sys.argv[3]
output_path = sys.argv[4]

celltypes = ["CD4", "CD8", "CD14", "CD19"]
wanted = set(celltypes)

protein_lengths = {}
with open(metadata_path, "r", newline="") as handle:
    reader = csv.DictReader(handle)
    required = {"Geneid", "Length", "gene_biotype"}
    if not required.issubset(set(reader.fieldnames or [])):
        raise ValueError("gene metadata is missing required fields")
    for row in reader:
        if row["gene_biotype"].strip() != "protein_coding":
            continue
        gene_id = row["Geneid"].strip()
        if not gene_id:
            raise ValueError("empty protein-coding gene identifier")
        if gene_id in protein_lengths:
            raise ValueError("duplicate protein-coding gene identifier: " + gene_id)
        length_text = row["Length"].strip()
        if not length_text:
            raise ValueError("empty gene length for: " + gene_id)
        length = float(length_text)
        if not math.isfinite(length):
            raise ValueError("non-finite gene length for: " + gene_id)
        protein_lengths[gene_id] = length

sample_to_celltype = {}
all_annotation_samples = set()
with open(samples_path, "r", newline="") as handle:
    reader = csv.DictReader(handle)
    required = {"sample", "celltype"}
    if not required.issubset(set(reader.fieldnames or [])):
        raise ValueError("sample annotation is missing required fields")
    for row in reader:
        sample = row["sample"].strip()
        celltype = row["celltype"].strip()
        if not sample:
            raise ValueError("empty sample identifier")
        if sample in all_annotation_samples:
            raise ValueError("duplicate sample identifier: " + sample)
        all_annotation_samples.add(sample)
        if celltype in wanted:
            sample_to_celltype[sample] = celltype

with open(expression_path, "r", newline="") as handle:
    reader = csv.reader(handle)
    header = next(reader)
    if header and header[0].startswith("\ufeff"):
        header[0] = header[0].lstrip("\ufeff")
    if len(header) < 2:
        raise ValueError("expression matrix has no sample columns")
    expression_samples = header[1:]
    if len(set(expression_samples)) != len(expression_samples):
        raise ValueError("duplicate expression sample identifier")
    expression_sample_set = set(expression_samples)
    missing_annotations = sorted(expression_sample_set - all_annotation_samples)
    missing_expression = sorted(all_annotation_samples - expression_sample_set)
    if missing_annotations or missing_expression:
        raise ValueError("expression and annotation sample identifiers do not match")
    indices = {celltype: [] for celltype in celltypes}
    for index, sample in enumerate(expression_samples, 1):
        celltype = sample_to_celltype.get(sample)
        if celltype is not None:
            indices[celltype].append(index)
    sample_counts = {celltype: len(indices[celltype]) for celltype in celltypes}
    if any(sample_counts[celltype] < 2 for celltype in celltypes):
        raise ValueError("fewer than two samples for a requested cell type")
    lengths = []
    means = {celltype: [] for celltype in celltypes}
    matched_genes = set()
    seen_expression_ids = set()
    for row_number, row in enumerate(reader, 2):
        if not row:
            continue
        if len(row) != len(header):
            raise ValueError("expression row has the wrong number of columns at line " + str(row_number))
        gene_id = row[0].strip()
        if gene_id in seen_expression_ids:
            raise ValueError("duplicate expression gene identifier: " + gene_id)
        seen_expression_ids.add(gene_id)
        if gene_id not in protein_lengths:
            continue
        matched_genes.add(gene_id)
        lengths.append(protein_lengths[gene_id])
        for celltype in celltypes:
            total = 0.0
            for index in indices[celltype]:
                value_text = row[index].strip()
                if not value_text:
                    raise ValueError("empty expression value at line " + str(row_number))
                value = float(value_text)
                if not math.isfinite(value):
                    raise ValueError("non-finite expression value at line " + str(row_number))
                total += value
            means[celltype].append(total / sample_counts[celltype])

if matched_genes != set(protein_lengths):
    missing_genes = sorted(set(protein_lengths) - matched_genes)
    raise ValueError("protein-coding metadata genes missing from expression matrix: " + str(len(missing_genes)))

with open(output_path, "w", newline="") as handle:
    writer = csv.writer(handle, delimiter="\t", lineterminator="\n")
    writer.writerow(["cell_type", "protein_coding_genes", "samples_averaged", "pearson_r", "abs_pearson_r"])
    for celltype in celltypes:
        correlation, _ = pearsonr(lengths, means[celltype])
        writer.writerow([
            celltype,
            len(lengths),
            sample_counts[celltype],
            "%.17g" % float(correlation),
            "%.17g" % abs(float(correlation))
        ])
PY

